function TextHash([string]$Text){$sha=[Security.Cryptography.SHA256]::Create();try{([BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::Unicode.GetBytes($Text)))).Replace('-','')}finally{$sha.Dispose()}}
function Probe([string]$Uri){try{$r=Invoke-WebRequest -UseBasicParsing -UseDefaultCredentials -Uri $Uri -TimeoutSec 15;[ordered]@{Passed=([int]$r.StatusCode-eq200);Status=[int]$r.StatusCode;Body=$r.Content}}catch{[ordered]@{Passed=$false;Error=$_.Exception.Message}}}
function NormalizeTaskXml([string]$Text){[xml]$xml=$Text;$ns=New-Object Xml.XmlNamespaceManager($xml.NameTable);$ns.AddNamespace('t','http://schemas.microsoft.com/windows/2004/02/mit/task');foreach($xpath in '/t:Task/t:Actions/t:Exec/t:Arguments','/t:Task/t:Actions/t:Exec/t:WorkingDirectory'){foreach($node in @($xml.SelectNodes($xpath,$ns))){$node.InnerText='<PHASE2_RELEASE_ACTION>'}};$restart=$xml.SelectSingleNode('/t:Task/t:Settings/t:RestartOnFailure',$ns);if($restart){$null=$restart.ParentNode.RemoveChild($restart)};$xml.OuterXml}
function Set-ExactDirectoryAcl([string]$Path,[string]$RuntimeRights){$null=New-Item -ItemType Directory -Path $Path -Force;$acl=Get-Acl $Path;$acl.SetAccessRuleProtection($true,$false);foreach($rule in @($acl.Access)){$null=$acl.RemoveAccessRuleAll($rule)};$inherit=[Security.AccessControl.InheritanceFlags]'ContainerInherit,ObjectInherit';$none=[Security.AccessControl.PropagationFlags]::None;$allow=[Security.AccessControl.AccessControlType]::Allow;$acl.AddAccessRule([Security.AccessControl.FileSystemAccessRule]::new('SYSTEM','FullControl',$inherit,$none,$allow));$acl.AddAccessRule([Security.AccessControl.FileSystemAccessRule]::new('BUILTIN\Administrators','FullControl',$inherit,$none,$allow));if($RuntimeRights){$acl.AddAccessRule([Security.AccessControl.FileSystemAccessRule]::new($runtimeIdentity,$RuntimeRights,$inherit,$none,$allow))};Set-Acl $Path $acl}
function Assert-Manifest([string]$Path,$Manifest){$actual=@(Get-ChildItem -LiteralPath $Path -File -Recurse -Force);if($actual.Count-ne@($Manifest.files).Count){throw "Manifest count mismatch: expected $(@($Manifest.files).Count), actual $($actual.Count)."};foreach($entry in $Manifest.files){$file=[IO.Path]::GetFullPath((Join-Path $Path $entry.relativePath));if(-not$file.StartsWith([IO.Path]::GetFullPath($Path).TrimEnd('\')+'\',[StringComparison]::OrdinalIgnoreCase)-or-not(Test-Path -LiteralPath $file -PathType Leaf)){throw "Manifest path invalid: $($entry.relativePath)"};$item=Get-Item -LiteralPath $file;if($item.Length-ne[int64]$entry.length-or(Get-FileHash -LiteralPath $file -Algorithm SHA256).Hash-ne$entry.sha256){throw "Manifest mismatch: $($entry.relativePath)"}}}
function Get-ExactProcess([string]$Release){$exe=Join-Path $Release 'DleOs.DevOperationalControlHost.exe';@(Get-CimInstance Win32_Process -ErrorAction SilentlyContinue|Where-Object{$_.ExecutablePath-and[string]::Equals($_.ExecutablePath,$exe,[StringComparison]::OrdinalIgnoreCase)}|ForEach-Object{$owner=Invoke-CimMethod -InputObject $_ -MethodName GetOwner -ErrorAction SilentlyContinue;[pscustomobject]@{Pid=[int]$_.ProcessId;ParentPid=[int]$_.ParentProcessId;Started=$_.CreationDate;Path=$_.ExecutablePath;Owner=if($owner.ReturnValue-eq0){$owner.Domain+'\'+$owner.User}else{$null}}})}
function Wait-Healthy([string]$Release,[int]$Seconds=120){$deadline=(Get-Date).AddSeconds($Seconds);do{Start-Sleep -Seconds 2;$processes=Get-ExactProcess $Release;$probe=Probe 'http://dle-os-host:5051/api/operations-center/v1/work-orders/0115622/verified-status-history';if($processes.Count-eq1-and$processes[0].Owner-ieq$runtimeIdentity-and$probe.Passed){return [ordered]@{Passed=$true;Process=$processes[0];FrontendTo5054=$probe}}}while((Get-Date)-lt$deadline);[ordered]@{Passed=$false;Processes=$processes;FrontendTo5054=$probe}}

$candidate=Get-ScheduledTask -TaskPath $candidatePath -TaskName $candidateName;$candidateInfo=Get-ScheduledTaskInfo -TaskPath $candidatePath -TaskName $candidateName;$beforeXml=Export-ScheduledTask -TaskPath $candidatePath -TaskName $candidateName;$legacyBefore=Export-ScheduledTask -TaskPath $legacyPath -TaskName $legacyName;$oldAction=@($candidate.Actions)[0];$oldRelease=[string]$oldAction.WorkingDirectory;$oldArguments=[string]$oldAction.Arguments;$oldExecute=[string]$oldAction.Execute;$oldRestartCount=[int]$candidate.Settings.RestartCount;$oldRestartInterval=[string]$candidate.Settings.RestartInterval;$eventChannel=Get-WinEvent -ListLog 'Microsoft-Windows-TaskScheduler/Operational';$eventWasEnabled=[bool]$eventChannel.IsEnabled
