 if(-not$candidate.Settings.Enabled-or$candidate.State-ne'Running'-or$candidate.Principal.UserId-inotmatch'DLE-OS-DEV-CONTROL'-or[string]$candidate.Principal.LogonType-ne'Password'-or[string]$candidate.Principal.RunLevel-ne'Limited'-or[string]$candidate.Settings.ExecutionTimeLimit-ne'PT0S'-or[string]$candidate.Settings.MultipleInstances-ne'IgnoreNew'){throw 'Candidate task is not at the qualified Phase 1 baseline.'}
