 $preflight=[ordered]@{Frontend5051=Probe 'http://dle-os-host:5051/shared';FrontendTo5054=Probe 'http://dle-os-host:5051/api/operations-center/v1/work-orders/0115622/verified-status-history';Canonical5052=Probe 'http://127.0.0.1:5052/api/platform/live/v1/readiness';CanonicalGuard=Probe 'http://127.0.0.1:5052/api/development/v1/security';OldProcess=Get-ExactProcess $oldRelease};$canonicalBody=if($preflight.Canonical5052.Passed){$preflight.Canonical5052.Body|ConvertFrom-Json}else{$null};$guardBody=if($preflight.CanonicalGuard.Passed){$preflight.CanonicalGuard.Body|ConvertFrom-Json}else{$null};if(@($preflight.GetEnumerator()|Where-Object{$_.Value.PSObject.Properties['Passed']-and-not$_.Value.Passed}).Count-ne0-or@($preflight.OldProcess).Count-ne1-or$canonicalBody.readinessVerdict-ne'Ready'-or$canonicalBody.database-ne'DLE_OS_CANONICAL_LIVE'-or$guardBody.verdict-ne'PASS'-or$guardBody.select-ne'PERMITTED'-or$guardBody.insert.result-ne'DENIED'-or$guardBody.update.result-ne'DENIED'-or$guardBody.delete.result-ne'DENIED'-or$guardBody.execute-ne'DENIED'){throw 'Runtime preflight failed.'};$result.Preflight=$preflight
