<?xml version="1.0" encoding="UTF-16"?>
<Task version="1.4" xmlns="http://schemas.microsoft.com/windows/2004/02/mit/task"><RegistrationInfo><Description>Read-only evidence capture when the DEV 5054 candidate action completes.</Description></RegistrationInfo><Triggers><EventTrigger><Enabled>true</Enabled><Subscription>$escaped</Subscription><Delay>PT5S</Delay></EventTrigger></Triggers><Principals><Principal id="Author"><UserId>S-1-5-18</UserId><LogonType>ServiceAccount</LogonType><RunLevel>HighestAvailable</RunLevel></Principal></Principals><Settings><MultipleInstancesPolicy>IgnoreNew</MultipleInstancesPolicy><DisallowStartIfOnBatteries>false</DisallowStartIfOnBatteries><StopIfGoingOnBatteries>false</StopIfGoingOnBatteries><AllowHardTerminate>true</AllowHardTerminate><StartWhenAvailable>true</StartWhenAvailable><RunOnlyIfNetworkAvailable>false</RunOnlyIfNetworkAvailable><Enabled>true</Enabled><Hidden>false</Hidden><ExecutionTimeLimit>PT5M</ExecutionTimeLimit><Priority>7</Priority></Settings><Actions Context="Author"><Exec><Command>powershell.exe</Command><Arguments>-NoLogo -NoProfile -NonInteractive -ExecutionPolicy Bypass -File &quot;$failureTool&quot;</Arguments><WorkingDirectory>$toolRoot</WorkingDirectory></Exec></Actions></Task>
"@;Register-ScheduledTask -TaskPath '\' -TaskName $watcherName -Xml $watcherXml -Force|Out-Null;$watcherCreated=$true
 $result.CandidateXmlBeforePath=Join-Path $runRoot 'candidate-before.xml';$beforeXml|Set-Content -LiteralPath $result.CandidateXmlBeforePath -Encoding Unicode;$result.CandidateXmlAfterPath=Join-Path $runRoot 'candidate-after.xml';$afterXml|Set-Content -LiteralPath $result.CandidateXmlAfterPath -Encoding Unicode;$result.Task=[ordered]@{BeforeSha256=TextHash $beforeXml;AfterSha256=TextHash $afterXml;OnlyApprovedFieldsChanged=$true;RestartCount=4;RestartInterval='PT2M';ExecutionTimeLimit='PT0S';MultipleInstances='IgnoreNew';OldRelease=$oldRelease;NewRelease=$newRelease;Principal=$after.Principal.UserId;LogonType=[string]$after.Principal.LogonType};$result.LegacyUnchanged=$true;$result.EventChannelEnabled=$true;$result.FailureWatcherTask=$watcherName;$result.Passed=$true
}catch{
 $result.Error=$_.Exception.Message;$result.RollbackInvoked=$taskChanged
 if($taskChanged){try{Stop-ScheduledTask -TaskPath $candidatePath -TaskName $candidateName -ErrorAction SilentlyContinue;$rollback=Get-ScheduledTask -TaskPath $candidatePath -TaskName $candidateName;$rollback.Settings.RestartCount=$oldRestartCount;$rollback.Settings.RestartInterval=$oldRestartInterval;$rollbackAction=New-ScheduledTaskAction -Execute $oldExecute -Argument $oldArguments -WorkingDirectory $oldRelease;Set-ScheduledTask -TaskPath $candidatePath -TaskName $candidateName -Action $rollbackAction -Settings $rollback.Settings|Out-Null;Start-ScheduledTask -TaskPath $candidatePath -TaskName $candidateName;$rollbackHealth=Wait-Healthy $oldRelease 150;$result.RollbackHealth=$rollbackHealth;$result.RollbackPassed=$rollbackHealth.Passed}catch{$result.RollbackError=$_.Exception.Message}}
